window.kbParts["paper-1e6f8c2e226daf2d"] = {"qs":{"江苏 2024 A类 申论#1":{"stem":"“给定资料1-4”列举了阅读活动中的一些新现象，展现了不同群体采用不同方式在阅读活动中取得的相应收获，请\n用一段话对此进行归纳概括。（20分）\n要求：紧扣给定资料，全面、准确。篇幅不超过250字。","options":[],"answer":"","analysis":"不同群体在不同阅读活动中取得相应收获：残障人士得益于《马拉喀什条约》的实施，特殊阅读需求关注度提\n升，获得更多无障碍阅读资源，享受阅读乐趣，提升社会融合度；公众对文博场馆的关注度日益提升，通过实地参\n观和数字化体验历史文化，实现了阅读的跨界延伸，满足对文化滋养的需求；老年人、社区居民等通过“有声图书\n馆”和城市书房，享受便捷舒适阅读服务，提升阅读新鲜感和吸引力，改变日常生活；人们通过有声特色航班、听书\nAPP等阅读新手段，高效利用碎片化时间，获取新闻热点、高价值话题和信息，丰富了阅读方式，激发阅读热情。\n   参考答案说明：本参考答案以“总结性引导语+不同群体在阅读活动中采用不同方式取得的收获”的结构呈现，具\n体收获分别从残障人士通过《马拉喀什条约》取得的收获、公众通过实地参观和数字化体验文博场馆取得的收获、\n老年人和社区居民等通过“有声图书馆”和城市书房取得的收获、人们通过有声特色航班和听书APP等阅读新手段取得\n的收获四个方面展开，各条答案要点之间在内容上相互并列，没有交叉，并以一段话的形式进行呈现。","figs":[],"state":"已标记","notes":[],"domains":["文化","公共管理"],"nature":"综合题","current":false,"links":[{"id":"k-da0e423a9d233834","label":"无障碍阅读资源的可及性有助于阅读障碍者参与文化生活和融入社会","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"获得更多无障碍阅读资源，享受阅读乐趣，提升社会融合度","why":"参考答案将无障碍资源、阅读体验和社会融合作为残障人士的相应收获。","origin":"逐题标记"},{"id":"k-32f76bad4e062125","label":"文博场馆的实地参观和数字化体验将阅读延伸到历史文化体验","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"实现了阅读的跨界延伸，满足对文化滋养的需求","why":"这一判断概括了公众通过实地参观或数字方式接触文物的收获。","origin":"逐题标记"},{"id":"k-556cded86ddda45b","label":"社区有声图书馆和城市书房通过扫码收听与就近阅读提高公共阅读服务的可及性","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"享受便捷舒适阅读服务，提升阅读新鲜感和吸引力，改变日常生活","why":"参考答案将阅读便利和吸引力的提升归为老年人及社区居民的收获。","origin":"逐题标记"},{"id":"k-18e801133ea5f58b","label":"有声阅读、播客和讲书短视频拓展碎片时间中的阅读与信息获取","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"高效利用碎片化时间，获取新闻热点、高价值话题和信息，丰富了阅读方式，激发阅读热情","why":"参考答案把碎片时间利用、信息获取和阅读兴趣归为数字阅读新方式带来的收获。","origin":"逐题标记"},{"id":"s-c898afc5816920c2","label":"跨材料提取并归并群体、方式与收获的对应关系","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"不同群体采用不同方式在阅读活动中取得的相应收获","why":"需要从四则材料提取群体及其阅读方式和收获，再将相近事例归并为并列要点。","origin":"逐题标记","originalId":"s-e0325057ca855625"}]},"江苏 2024 A类 申论#2":{"stem":"“给定资料5-6”中提到的“阅读推广”与“阅读推销”是现实生活中的常见现象，这两类现象涉及哪些问题？请围绕这\n些问题谈谈你的认识。（20分）\n要求：归类合理，观点正确，分析透彻，见解深刻。篇幅300字左右。","options":[],"answer":"","analysis":"阅读推广是通过丰富的形式向读者传播书香，普及阅读的公益活动，旨在让人富有底气、树立文化自信，要大\n力支持。但由于推广宣传力度不够，阅读活动较少，导致持续性和创新性不足，影响力亟待扩大。\n  阅读推销则是利用直播等现代营销手段快速售书的营销模式，需要审慎对待。虽取得一定市场成效，但由于当\n前图书价格立法缺失，主播定位偏差，使得推销过度商业化，图书质量参差不齐，直播方式轻浮、模式雷同，甚至\n出现低价盗版书等问题，长此以往必将损害阅读文化的健康发展。\n  因此，两者应有机结合，取长补短。阅读推广可借鉴推销的营销策略，提高活动吸引力和实效性，吸引更多人\n加入；而阅读推销也应注重图书质量与文化内涵，避免低俗化，同时打击低价盗版书，共同营造一个更加健康、多\n元的阅读环境。\n  参考答案说明：思路方面，本参考答案按照观点现象分析题“解释抽象观点、现象+表态+分析论证+总结”的一般\n答题思路展开。内容方面，本参考答案先阐释了“阅读推广”“阅读推销”的含义，再分别对两者表态；“分析论证”部\n分，按照题干要求重点分析了“问题”，此外，“阅读推销”中也根据资料写入了成绩；最后对“阅读推广”“阅读推销”进了\n总结，突出了改进措施。词句表达方面，本答案加上了“但”“因此”等连接词来承接上下文。","figs":[],"state":"已标记","notes":[],"domains":["文化"],"nature":"综合题","current":false,"links":[{"id":"k-a0588a544fbce877","label":"公益性阅读推广与直播图书推销的区别","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"先阐释了“阅读推广”“阅读推销”的含义","why":"公益性阅读推广旨在普及阅读，直播图书推销以售书为直接目标，两者的目的决定了评价侧重点。","origin":"逐题标记"},{"id":"k-13180bbfd51c959f","label":"完善全民阅读推广服务体系","catalog_id":"4d94680ab5558551","type":"观点与论证","role":"直接考查","field":"answer","quote":"推广宣传力度不够，阅读活动较少","why":"活动供给不足和宣传覆盖有限会制约推广的持续性和影响力，改进需兼顾活动供给与传播方式。","origin":"逐题标记"},{"id":"k-6253dd617cc2760b","label":"直播售书过度追求低价的风险","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M2","quote":"一味低价破坏了商品的正常流通，现在已经出现了专门为直播渠道制作的","why":"材料以直播低价竞争和盗版书为例，说明过度追求低价可能扰乱图书流通并损害阅读环境。","origin":"逐题标记"},{"id":"k-9c740739994c2e6b","label":"阅读推广与图书推销取长补短的条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"阅读推销也应注重图书质量与文化内涵","why":"阅读推广可借鉴营销方式扩大触达，图书推销可通过优质选书和有内容的分享促进阅读。","origin":"逐题标记"},{"id":"s-75a1eb1e46268fd8","label":"按现象归类提炼材料中的问题","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"这两类现象涉及哪些问题？","why":"需要将分散在不同人物叙述中的问题按阅读推广和阅读推销归类，并合并同类信息。","origin":"逐题标记","originalId":"s-f093fc77cc374c94"},{"id":"s-93367fee5c934df6","label":"依据材料分析现象的成因与影响并提出改进措施","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"最后对“阅读推广”“阅读推销”进了","why":"需要从材料中的具体做法和结果推导其成因与影响，再提出与所归纳问题相对应的改进措施。","origin":"逐题标记","originalId":"s-9e6c626575d3b92e"}]},"江苏 2024 A类 申论#3":{"stem":"在J省文旅厅2023年度“书香支部品质阅读”活动中，紫金图书馆党支部以“‘品诗词之美 扬文化自信’主题党日活\n动”申报了“最美阅读案例”评比。假如你是J省文旅厅评比活动的一名评委，将对该案例进行点评，请根据“给定资料\n7”，草拟点评的主要内容。（20分）\n要求：突出特色，内容全面；建议切当，条理清楚。篇幅350字左右。","options":[],"answer":"","analysis":"一、成果：紫金图书馆紧跟社会古典诗歌热潮，举办“品诗词之美 扬文化自信”的阅读活动，提升了党员干部能力\n素质，激发了读书学习的积极性和主动性，值得肯定。\n  二、活动特色：活动环节设置丰富，理论学习环节感悟深刻，组织党员干部集中学习领导人关于文化传承的讲\n话精神，深刻领会了新时代新的文化使命重要论断的重大意义和内涵要义；诗词品评环节丰富多彩，鼓励青年用多\n种方式分享阅读心得，并结合工作实际，诠释对诗词的解读与感悟，鼓励青年人在实际工作中要直面困难和挑战，\n展现责任和担当，拓展人生境界；总结点评环节指导性强，帮助党员干部指明了今后的工作方向，并推荐了书单，\n布置了下次活动任务。\n  三、问题及建议：但本次活动参与主体仅有青年人，活动形式传统，影响力不够。建议今后举办过程中，与多\n部门共同联办活动，动员全体工作人员参与，丰富活动形式内容，并利用融媒体积极推广活动成果，形成“风成于\n上，俗化于下”的示范效应，引领全民阅读。\n  参考答案说明：本参考答案从“成果”“活动特色”“问题及建议”三个方面展开，各条答案要点之间在内容上相互并\n列，没有交叉。","figs":[],"state":"待核","notes":["参考答案称“参与主体仅有青年人”，材料记载活动面向全体党员干部，青年党员代表承担诗词分享。扩大参与的建议可依据分享主体仍可拓展。"],"domains":["文化"],"nature":"综合题","current":false,"links":[{"id":"k-b7eb41738f0894fb","label":"党员干部带头读书对全民阅读的示范作用","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"已成为引领全民阅读的重要力量","why":"材料以干部阅读的示范效应说明支部活动带动群众阅读的价值。","origin":"逐题标记"},{"id":"k-ceda05910bdf22b8","label":"以多样化诗词品评联系岗位实践","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"以演讲、角色表演、PPT展示等方式分享自己钟爱的诗词篇章，并联系图书馆工作实际","why":"活动以多种方式分享诗词，并结合岗位实践体会责任担当和应对挫折的态度，是案例的一项特色。","origin":"逐题标记"},{"id":"k-23ca9982fb801827","label":"通过跨部门联办和融媒体传播扩大阅读活动覆盖面","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"部门共同联办活动，动员全体工作人员参与，丰富活动形式内容，并利用融媒体积极推广活动成果","why":"联办和动员可扩大参与范围，融媒体传播可扩大活动成果的触达范围。","origin":"逐题标记"},{"id":"s-c8dfde3ede3eadab","label":"按成效、特色和改进建议组织案例点评","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"从“成果”“活动特色”“问题及建议”三个方面展开","why":"需要从材料提炼活动成效和特色，并针对可改进之处提出具体建议，形成条理清楚的点评。","origin":"逐题标记","originalId":"s-7513b7cf36370e95"}]},"江苏 2024 A类 申论#4":{"stem":"请根据“给定资料8”中习近平总书记对全民阅读的要求，围绕“诗书满腹拓展人生，全民阅读引领未来”这一主题，\n写一篇文章。（40分）\n要求：\n（1）自选角度，自拟标题；\n（2）参考给定资料，不拘于给定资料；\n（3）观点明确，内容充实，结构完整；\n（4）篇幅1000字左右。","options":[],"answer":"","analysis":"书香盈满人生路，全民阅读启新程\n   在浩瀚的历史长河中，中华民族以阅读为舟，穿越时间的波涛，传承千年的智慧与文明。时至今日，“全民阅\n读”已成为国家文化战略的重要组成部分。习近平总书记在《致首届全民阅读大会举办的贺信》中，更是对全民阅读\n寄予厚望，希望广大党员、干部、孩子乃至全社会都能积极参与，形成浓厚的阅读氛围，这不仅是对个人成长的期\n许，更是对国家发展的深刻展望。\n   阅读塑造个体精神风貌，提升国民综合素质。它不仅能够丰富我们的知识储备，正心明德，更能传承精神，塑\n造品格。古人云：“书犹药也，善读之可以医愚。”历史的长河中，无数先贤通过阅读汲取前人的智慧，进而在各自领\n域取得了卓越的成就。对于个人而言，坚持阅读，意味着不断学习新知识，掌握新技能，从而在竞争激烈的社会中\n立于不败之地。正如习近平总书记所言，广大党员、干部应带头读书学习，修身养志，增长才干，这不仅是对党员\n干部的要求，也是对每一个追求成长的人的鞭策。通过阅读，我们可以更好地认识世界，理解人生，实现自我价值\n的升华。\n   阅读坚定文化自信，增强国家软实力。全民阅读的推广，不仅仅是对传统文化的继承和弘扬，更是一种深层次\n的文化自觉与文化自信的表现。“阅读，是心灵的粮食，也是文化的灯塔。”通过广泛而深入的阅读，民众能够更全面\n地了解本土文化的丰富内涵和独特价值，从而在内心深处生发出对本土文化的强烈认同感和自豪感，这是文化自信\n的重要基石，它使得民众在面对外来文化时，能够更加坚定地站在本土文化的立场上，展现出更加深厚和坚定的文\n化自信。因此，全民阅读不仅是一项文化活动，更是一种文化战略，它对于提升国家文化软实力、增强国际文化影\n响力具有不可估量的价值。\n\n  故此，我们要深入推进全民阅读，建设“书香中国”。要完善制度保障和基础设施建设，多元化开展阅读活动，\n丰富阅读形式，营造浓厚的读书氛围。在制度保障方面，我们可以制定更加完善的阅读推广政策，为全民阅读提供\n坚实的制度支撑。同时，加大对图书馆、阅览室等公共场所的投入，为民众提供更加便捷、舒适的阅读环境。此\n外，可以通过举办各种形式的读书会、讲座、展览等，吸引不同年龄段、不同兴趣爱好的人群参与。而除了传统的\n纸质书籍，我们还可以推广电子阅读、有声阅读等多种形式，满足不同人群的阅读需求。如此，方能营造出浓厚的\n读书氛围，让阅读成为每个人生活中不可或缺的一部分，共同铸就“书香中国”的美好图景。\n  在书香袅袅中，我们共绘“书香中国”的壮美画卷。每一颗热爱阅读的心灵，都是这幅画卷上最动人的笔触。让阅\n读成为生活的常态，让书香盈满每一个角落，不仅滋养个人的心灵，也丰盈国家的文化底蕴。在这书香四溢的旅程\n中，我们共同前行，共创一个智慧与希望并蓄的未来。\n文章分析\n                   书香盈满人生路，全民阅读启新程\n  【标题的优点：首先，范文的标题“书香盈满人生路，全民阅读启新程”突出了“诗书满腹拓展人生，全民阅读引\n领未来”这一主题。其次，在形式上采用对称式结构，使标题更有亮点。】\n  （1）在浩瀚的历史长河中，中华民族以阅读为舟，穿越时间的波涛，传承千年的智慧与文明。时至今日，“全民\n阅读”已成为国家文化战略的重要组成部分。（2）习近平总书记在《致首届全民阅读大会举办的贺信》中，更是对全\n民阅读寄予厚望，希望广大党员、干部、孩子乃至全社会都能积极参与，形成浓厚的阅读氛围，这不仅是对个人成\n长的期许，更是对国家发展的深刻展望。\n  【开头的优点：★内容方面。范文的开头是紧扣题目给定的“诗书满腹拓展人生，全民阅读引领未来”这一主题展\n开的。首先，介绍了自古至今中华民族都重视阅读；其次，指出了习近平总书记重视阅读，并希望全社会有浓厚的\n阅读氛围。★文字表达方面。使用了“不仅”“更是”等连接词，使语言表达有逻辑性。】\n  阅读塑造个体精神风貌，提升国民综合素质。它不仅能够丰富我们的知识储备，正心明德，更能传承精神，塑\n造品格。（1）古人云：“书犹药也，善读之可以医愚。”历史的长河中，无数先贤通过阅读汲取前人的智慧，进而在\n各自领域取得了卓越的成就。（2）对于个人而言，坚持阅读，意味着不断学习新知识，掌握新技能，从而在竞争激\n烈的社会中立于不败之地。（3）正如习近平总书记所言，广大党员、干部应带头读书学习，修身养志，增长才干，\n这不仅是对党员干部的要求，也是对每一个追求成长的人的鞭策。通过阅读，我们可以更好地认识世界，理解人\n生，实现自我价值的升华。\n  【论述段1的优点：★观点句：范文的观点句是紧扣“诗书满腹拓展人生，全民阅读引领未来”这一文章主题提出\n的。形式上，它在段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它\n是围绕“阅读塑造个体精神风貌，提升国民综合素质”展开。★论述内容：（1）介绍了阅读对先贤的重要性；（2）介\n绍了阅读对个人的重要性；（3）广大党员干部要带头读书学习；（4）总结性的指出阅读的重要性。注意：以上四\n个方面的内容都是紧扣“阅读塑造个体精神风貌，提升国民综合素质。它不仅能够丰富我们的知识储备，正心明德，\n更能传承精神，塑造品格”这个观点句论述的，论述的针对性强，内容层次丰富。在论述方法上采用了讲道理、举例\n子相结合，做到了丰富多样。】\n  阅读坚定文化自信，增强国家软实力。全民阅读的推广，不仅仅是对传统文化的继承和弘扬，更是一种深层次\n的文化自觉与文化自信的表现。（1）“阅读，是心灵的粮食，也是文化的灯塔。”通过广泛而深入的阅读，民众能够\n更全面地了解本土文化的丰富内涵和独特价值，从而在内心深处生发出对本土文化的强烈认同感和自豪感，这是文\n化自信的重要基石，它使得民众在面对外来文化时，能够更加坚定地站在本土文化的立场上，展现出更加深厚和坚\n定的文化自信。（2）因此，全民阅读不仅是一项文化活动，更是一种文化战略，它对于提升国家文化软实力、增强\n国际文化影响力具有不可估量的价值。\n  【论述段2的优点：★观点句：范文的观点句是紧扣“诗书满腹拓展人生，全民阅读引领未来”这一文章主题提出\n的。形式上，它在段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它\n是围绕“阅读坚定文化自信，增强国家软实力”展开。★论述内容：（1）阅读对民众了解本土文化的重要性；（2）全\n民阅读的重要价值——文化战略。注意：以上两个方面的内容都是紧扣“阅读坚定文化自信，增强国家软实力。全民\n阅读的推广，不仅仅是对传统文化的继承和弘扬，更是一种深层次的文化自觉与文化自信的表现”这个观点句论述\n的，论述的针对性强，内容层次丰富。在论述方法上采用了讲道理、举例子相结合，做到了丰富多样。】\n  故此，我们要深入推进全民阅读，建设“书香中国”。要完善制度保障和基础设施建设，多元化开展阅读活动，\n丰富阅读形式，营造浓厚的读书氛围。（1）在制度保障方面，我们可以制定更加完善的阅读推广政策，为全民阅读\n提供坚实的制度支撑。（2）同时，加大对图书馆、阅览室等公共场所的投入，为民众提供更加便捷、舒适的阅读环\n境。（3）此外，可以通过举办各种形式的读书会、讲座、展览等，吸引不同年龄段、不同兴趣爱好的人群参与。而\n除了传统的纸质书籍，我们还可以推广电子阅读、有声阅读等多种形式，满足不同人群的阅读需求。如此，方能营\n造出浓厚的读书氛围，让阅读成为每个人生活中不可或缺的一部分，共同铸就“书香中国”的美好图景。\n  【论述段3的优点：★观点句：范文的观点句是紧扣“诗书满腹拓展人生，全民阅读引领未来”这一文章主题提出\n的。形式上，它在段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它\n\n是围绕“如何推进全民阅读”展开。★论述内容：（1）如何推进全民阅读——制度保障；（2）如何推进全民阅读——\n加大投入；（3）如何推进全民阅读——举办活动。注意：以上三个方面的内容都是紧扣“我们要深入推进全民阅读，\n建设‘书香中国’。要完善制度保障和基础设施建设，多元化开展阅读活动，丰富阅读形式，营造浓厚的读书氛围”这个\n观点句论述的，论述的针对性强，内容层次丰富。在论述方法上采用了讲道理、举例子相结合，做到了丰富多\n样。】\n  【论述段之间的关系：★内容的内在逻辑：范文的论述段之间是依照“意义-对策”的逻辑展开的。论述段1和论述\n段2分别从“塑造个体精神风貌，提升国民综合素质”“坚定文化自信，增强国家软实力”两个方面论述了阅读的意义；论\n述段3通过“建设书香中国”论述了如何推动全面阅读的对策。】\n  在书香袅袅中，我们共绘“书香中国”的壮美画卷。每一颗热爱阅读的心灵，都是这幅画卷上最动人的笔触。让阅\n读成为生活的常态，让书香盈满每一个角落，不仅滋养个人的心灵，也丰盈国家的文化底蕴。在这书香四溢的旅程\n中，我们共同前行，共创一个智慧与希望并蓄的未来。\n  【结尾的优点：范文的结尾回扣了“诗书满腹拓展人生，全民阅读引领未来”这个主题，并且进行了总结提升。】","figs":[],"state":"已标记","notes":[],"domains":["文化"],"nature":"综合题","current":false,"links":[{"id":"k-0f94b35ea73dc683","label":"全民阅读要求党员干部带头读书、儿童养成阅读习惯、全社会共同参与","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"M1","quote":"希望广大党员、干部带\n头读书学习，修身养志，增长才干；希望孩子们养成阅读习惯，快乐阅读，健康成长；希望全社会都参与到阅读中\n来，形成爱读书、读好书、善读书的浓厚氛围。","why":"题干明确要求依据材料8中的全民阅读要求立论，这段话交代了各类主体的参与要求。","origin":"逐题标记"},{"id":"k-adb11b1be2d2966e","label":"持续阅读通过增进知识、涵养品格和提升才干拓展个体人生","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"阅读塑造个体精神风貌，提升国民综合素质。","why":"参考文章从积累知识、正心明德和增长才干展开论证，对应题设的个人成长维度。","origin":"逐题标记"},{"id":"k-c4b7f218db8900c1","label":"全民阅读通过增进传统文化理解和认同坚定文化自信","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"从而在内心深处生发出对本土文化的强烈认同感和自豪感","why":"参考文章把理解本土文化、形成文化认同和坚定文化自信连成因果链，对应题设的社会发展维度。","origin":"逐题标记"},{"id":"k-13180bbfd51c959f","label":"完善全民阅读推广服务体系","catalog_id":"4d94680ab5558551","type":"制度与规则","role":"解题依据","field":"answer","quote":"要完善制度保障和基础设施建设，多元化开展阅读活动，\n丰富阅读形式，营造浓厚的读书氛围。","why":"参考文章用制度保障、公共阅读设施和多样服务说明推广全民阅读的具体条件。","origin":"逐题标记"},{"id":"s-4fdadcb77809c673","label":"为给定主题提炼分论点并按意义与对策组织论证","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"范文的论述段之间是依照“意义-对策”的逻辑展开的。","why":"题目要求观点明确、结构完整，参考文章先分述个人与社会层面的意义，再提出推进措施。","origin":"逐题标记","originalId":"s-b6d95ed54b33d819"}]}},"mats":{"d9143fe68692ffc0":["材料1","材料1\n  “我看不见这个世界，但我想让世界看见我。”纪录片《让世界看见我》讲述的是中国盲人登山第一人张洪成功登\n顶珠穆朗玛峰的经历。2023年4月23日，在第二届全民阅读大会的阅读权益保障论坛上，导演范立欣带来的这部电影\n深深打动了观众。普通人很难想象，“让世界看见我”对很多残障人士而言，是一种多么大的幸福。《马拉喀什条约》\n的生效实施，让这种幸福来得特别强烈。\n  《马拉喀什条约》全称是《关于为盲人、视力障碍者或其他印刷品阅读障碍者获得已出版作品提供便利的马拉\n喀什条约》。2023年5月5日，是《马拉喀什条约》对中国生效一周年，在电影《长空之王》无障碍公益专场首映礼\n之后，一位视障观众激动地说，以前从没想过能比普通观众更早看到一部电影，感觉特别满足。视障儿童小禹说，\n因为有了《马拉喀什条约》，今后她会听到更多精彩的故事，欣赏到更多的有声读物。\n  “这里有盲文书和听书机吗？”“当然，请跟我去视障阅览室吧！”2023年5月21日，第33个全国助残日，来自新疆\n阿克苏地区的20位盲童走进杭州图书馆。在青年馆员小王的引领下，盲童与机器人无障碍沟通，在视障阅览室开展\n文化体验和交流活动。《飞天英雄》《女生贾梅全传》《哈利波特》……一进入视障阅览室，小读者们顺利地找到\n了自己喜欢的书籍，开始了津津有味地阅读。二楼音乐分馆HIFI室内，盲童小读者们双手捧起清茶和桂花干，细嗅杭\n州的特有味道。“今天我们就随着这沁人心脾的茶香，走进杭州的一年四季吧！”在娓娓讲述的四季古诗词中，盲童小\n读者们通过文字“游览”杭州。据了解，本次走进杭州图书馆活动作为“启明行动”的第一站，由浙江省对口支援新疆阿\n克苏地区和兵团第一师指挥部、中共阿克苏地委教育工委等单位联合主办。\n  “自从《马拉喀什条约》生效以来，各级媒体的报道、相关部门的宣传使得大家对视障者、听障者等阅读障碍者\n的特殊阅读需求有了更多了解。”作为一名视障人士，清华大学社会工作专业硕士研究生小梁有着更深刻的感受。他\n说，在社会大众关注条约、关注阅读障碍者需求的氛围中，社会的无障碍软硬件发展都得到了更多支持，障碍人群\n尤其是残障者的社会融合也更多提升。“未来，《马拉喀什条约》一定会为相关障碍群体获得文化产品提供更多便\n利，这个世上不幸有盲人，但阅读不应该有盲区。”",["4fbf1d8260d6665235b0.pdf",1]],"0d7e82bec5f3df52":["材料2","材料2\n  长假孩子哪里去？博物馆榜单来参考。上海博物馆、故宫博物院、中国国家博物馆、南京博物院、苏州博物\n馆……近日，一份“中博热搜榜”出炉，榜单罗列了100家博物馆，几乎每个省份均有上榜，榜单中的排名引发网友热\n议。有网友说“陕历博才是我心中的文博老大”，也有网友表示“讲真，山西博物院严重被低估了”，不过也有网友认\n为“这只是博物馆热搜榜，和最好博物馆排名是两码事”……不管大家如何争论，都印证了当下大众对文博场馆的关注\n度越来越高的事实。\n   文物是凝固的历史，诉说着古老的故事。文博场馆就是一处盛放历史的“容器”，你曾读过的书，你曾听过的故\n事，在这个“容器”里可以神奇地与一件件具体的文物关联在一起，让你在惊讶中留下抹不去的印痕。到博物馆去，某\n种程度上可以看作是阅读的跨界和延伸，与茅台、咖啡跨界组合的爆红“酱香拿铁”不一样，这场起步于阅读的跨界似\n乎走得更远、影响更大。\n   “哇，这个画家我知道，他是江南四大才子之一！”“这把剑跟书上描绘得一模一样，古人真的了不起！”……刚刚\n过去的国庆“黄金周”长假，全国各大文博场馆火爆难约。据江苏智慧文旅平台监测数据，黄金周前4天，南京博物院\n接待10.5万人次，扬州中国大运河博物馆接待7.7万人次，位居全省文博场馆前列。引人关注的是，南京博物院一口\n气“上新”五个艺术新展，讲解每天增至8场。中国大运河博物馆每天约有1.8万人次参观，越来越多的年轻人甚至小朋\n友走进博物馆触摸历史心跳，感受文化气息。\n   取得这样的成绩，一方面得益于博物馆自身的苦练内功，另一方面则在于不断贴合受众“另类阅读”需求的创新挖\n掘，让“深巷酒香”以大众更喜闻乐见的方式飘得更远。今年4月，敦煌研究院和腾讯联合打造的“数字藏经洞”上线，将\n敦煌藏经洞及室藏6万多卷珍贵文物搬上“云端”，观众只需根据提示点击，就可以沉浸式体验国宝级文物的前世今\n生。“镇馆之宝”变身有趣的冰箱贴、人人皆可DIY的文物丝巾、造型各异的文创美食……博物馆文创一次次的花样“出\n圈”，也让文物以更丰富的载体形式走进寻常百姓家。当越多人为了一份榜单展开“唇枪舌剑”之时，就越发印证着，\n公众对文化滋养的需求有多强烈，阅读的支脉就会延伸得有多远。",["4fbf1d8260d6665235b0.pdf",1]],"8b2ffe56acde6f71":["材料3","材料3\n  “想要阅读什么书籍，只要用手机扫一扫墙上的二维码，它就会立马‘说话’，真简单！”近日，盐城市龙冈镇新时\n代文明实践所里的“有声图书馆”格外引人注目，墙面上的“书籍”内容丰富，涵盖世界名著、国学经典、艺术之旅等十\n个方面，群众可以根据自身兴趣进行个性化选择，无需下载任何软件，扫码即能在线收听。\n\n  出门借书不方便、视力不好看书费力……“有声图书馆”有效破解了老人的阅读难题，成为村居（社区）公共文化\n服务的新载体。“知识都装在一个个‘二维码’里，过去是‘定时学’‘集中学’，现在是‘便捷学’‘自主学’，只要手机扫一扫就\n可以学习党的政策，还可以听歌，真是太方便了。”龙冈镇老党员老桂说。\n  扬州市民小倪对阅读的感情更多集中在家门口的城市书房上，一年多以来，小倪每天抽出时间，来城市书房学\n习一会儿，起初是半小时，不久后是一小时，现在养成了每天两小时的学习习惯。“很方便，一转角就到！城市书房\n的书籍更新频率高，而且还有志愿者不定期收集我们的需求。这样的好地方能自然拉近人与阅读、学习的关系，持\n续产出新鲜感和吸引力，阅读作为一种生活方式正在潜移默化地改变我们的日常。”\n  近年来，城市书房如雨后春笋般涌现，在全国快速生长。作为一种新型公共文化空间，城市书房开进了大街小\n巷、商圈乃至景区，这个“一转角就到的精神充电站”带给许多人舒适的阅读体验。城市书房规模适中、布局灵活，街\n心闹市、镇角村口、小区校旁皆可安身，可新建，也可在城市微更新中盘活用好各种闲置设施。日前，江苏省人大\n常委会第三十二次会议审议通过的一项新法规——《扬州市城市书房条例》，引发社会各界广泛关注。作为我国首\n部以城市书房为主题的地方性法规，该条例明确了建设、管理、运行以及服务内容和要求，确立了城市书房的法律\n地位，是城市书房相关工作进入法治化新时代的一大体现。",["4fbf1d8260d6665235b0.pdf",1]],"f8da04ef08fa9c4a":["材料4","材料4\n  “女士们、先生们，很高兴与您在万米高空相遇，从宁波飞往首都北京。在旅途中，我们将为您提供数字阅读有\n声服务，邀您享受美妙阅读时光，愿您开卷有益，前程万里……”2023年10月31日下午，伴随着这段客舱广播，一场\n特别的数字阅读与读书会，在宁波飞往北京大兴机场的我国东航MU5179航班上进行，这也是全国首趟以数字阅读为\n主题的有声特色航班。机上137名旅客在云端品味书香，共同开启了一段“阅读引领，精神共富”的精彩旅程。\n  航班进入平飞后，乘务员向旅客提供有声阅读耳机，从当季热门文化类节目《典籍里的中国》到小说《人世\n间》、评书《黑虎传》……旅客们在云端进入高品质的有声阅读世界。“没想到旅途中能以这样的方式参与阅读，非\n常有意义。”“在飞机上，手机暂时断网，我也从忙碌的社交中静了下来，真正享受到了读书的快乐。”旅客们纷纷为\n主题航班点赞。\n  随着互联网新技术、新平台的不断推陈出新，人们获取信息的方式在不断演进，读书也不例外，各具特色的阅\n读新景观正层出不穷地涌现。\n  在多个听书APP上可以看到，各种类型的有声书目非常丰富，既包括《孙子兵法》《资治通鉴》《红楼梦》等\n传统经典，也包括《三体》《盗墓笔记》《雪中悍刀行》等当下流行图书。一位90后妈妈说：“听书可以解放双手、\n双眼，将碎片化时间利用起来，连做家务时都可以听书。在我家，听书还是哄孩子睡觉的神器。每天晚上孩子睡觉\n前我就用手机给她播放童话故事，我则看自己的书，两不耽误。”酷狗音乐发布的《2023听书生态报告》显示，用户\n有声书收听时长较去年同比增长27.5%。在听书平台上还出现了一个新职业——播客。播客基于个人化表达，输出某\n一类价值观点的移动音频内容，也受到了年轻人的喜爱。喜马拉雅数据显示，播客收听用户主要为80后、90后年轻\n人，占比37.1%。人们通过播客获取新闻热点、高价值话题和信息，让碎片时间变得更有价值。\n   听书才刚刚熟悉，短视频讲书又成为新的热点。记者在抖音平台看到，读书内容创作者“止庵”的“世界文学大师\n解读”合集累计播放量461万次，“1379号观察员”的“解读《百年孤独》”合集累计播放量已超739万次……北京市民孙\n女士说：“我喜欢看读书短视频，这样可以对没有读过的书进行初步了解，决定是否再仔细读这本书。对于读过的书\n则可以听听别人对作品的见解，加深理解。”《BILIBILI读书生态报告》显示，过去一年，B站读书类视频总播放量超\n58亿次，同比增长118%；约74.3万人每天在B站至少观看一个读书视频，同比增长779%。不知不觉间，“视频化阅\n读”已然成为一种新浪潮。\n   从电子书、有声书到现在的听书、短视频读书、荐书，阅读的方式在悄然发生着变化，丰富多彩的阅读形式极\n大激发了越来越多人的阅读热情。未来的阅读会变成什么样，也许我们现在还看不明白。",["4fbf1d8260d6665235b0.pdf",2]],"c2c3d1df71177d6c":["材料5","材料5\n   阅读推广人，你听说过吗？让我们走进他们的生活，听听这些阅读推广人的心里话。\n   苏州《月月书房》主理人孙月月：我的家乡苏州很有意思，从小我就被苏州文化所浸润。我家在沧浪亭街2号，\n左边是沧浪亭，五百名贤祠所在的地方；右边是公元1035年范仲淹创办的千年府学。后来我在苏州广电开始做文化\n类节目，越来越觉得苏州就是一座天然的“图书馆”。《月月书房》从我和女儿的一封家书开始，最初只是“月月姐\n姐”我一个人写公众号，后来慢慢发展成为一群人围炉而坐的读书会。接着，我们又把“指尖的阅读”变成了用脚步去\n丈量的“走读”。我们和专家学者带领读者一起走进苏州园林街巷、古镇乡村，实地打开苏州悠久浩瀚的文脉，以现场\n直播、短视频推送、推文分享等丰富形式，向更多读者隔屏传播姑苏书香。我觉得，读书不是为了装点门面、附庸\n风雅，而是让人成为一个有底气的人、文化自信的人。\n   深圳阅读推广人李黎众：我是从参加图书馆组织的亲子阅读活动开始的，那时类似的活动还不够多，名额“秒\n抢”都不一定能获得。后来听说报名做义工就可以参加活动，我就从此走上了作为阅读推广践行者的公益之路。我之\n前从事过人力资源方面的工作，参与阅读推广之后，我广泛学习了心理知识、文学知识和沟通技巧，几乎成了一\n个“杂学家”。在面向孩子们阅读推广的课堂上，绘画、戏剧、吟诵、创作以及盒子剧场，都是我擅长的。很快我就认\n识到，阅读是陪伴人一生的，并不只是小的时候才需要阅读。如今，我的推广活动从图书馆、学校课堂，延伸到许\n\n多社区。现在基本一年要进行几百场推广活动，在深圳有许多“守阅人”跟我一样，为了打造文化之城、阅读之城，大\n家在一起努力着。",["4fbf1d8260d6665235b0.pdf",2]],"1f92ca026e51282a":["材料6","材料6\n  “3、2、1，上链接！”网络时代，直播带货风行。眼下，图书与直播间也似乎正在越来越紧密地联系在一起。以\n下是几位有过直播间购书经历者的感受。\n  媒体工作者90后女孩珊珊：有一次，在看短视频时无意刷到了直播卖书，点进去发现里面几乎没有名著，仅有\n的一两本，还是“烂大街”的，那次之后对直播卖书就蛮失望的，没再关注过。对于直播卖书，我一直有个疑惑：真正\n能沉下心看书的人，会去刷直播吗？\n  IT软件工程师00后女孩奇奇：曾经在抖音直播间买过一本悬疑类图书，那个主播很有气质，声音也好听，在介\n绍图书时还会朗读，一下子吸引了我。距离买书大约过去半年了吧，不记得放哪里了，还没翻过。\n  实体书店负责人小蔚：直播间我进去过，也买过两本书。我觉得直播间的气质是轻浮的，直播+成功学+低价，\n是他们的统一模式。图书是特殊的商品，一味低价破坏了商品的正常流通，现在已经出现了专门为直播渠道制作的\n低价盗版书。国外不少国家的图书价格立法，新书18个月内为受保护期，零售商不可以对书变相打折。我们没有这\n方面的立法，这恐怕也是直播卖书在我国特别流行的原因吧。\n  在直播卖书动辄几万册销量的同时，这些评价似乎颇为刺眼，但直播间卖书也有好评如潮的时候，知名文化人\n董先生的直播间被人评价为这领域的一股“清流”。有数据显示，他在抖音平台一个月内卖了约266万单书，其中的热\n门单品如《苏东坡传》《在岁月中远行》等，继续“火”到了传统图书电商畅销总榜和新书热卖榜前列，荐书语里甚至\n专门提示“董主播力推”。有网友分析，董主播的成功是把直播间变成了讲台，其丰富的知识结构、深厚的文化素养与\n图书卖点相互交织，成为当下卖书的有效“话术”。比如在介绍《苏东坡传》时，他讲了近半小时苏轼的故事，讲三次\n被贬的苏轼仍然洒脱乐观，这个态度值得我们学习，他说：“人生缘何不快乐，只因未读苏东坡。”当晚，《苏东坡\n传》卖掉2万多本。一位网友说：“我在董主播的直播间里买东西，感觉就像上了抖音夜大，自觉交学费然后下单。”\n  阅读推广人、中央广播电视总台主持人贺老师认为，董主播的魅力在于把自己定位在一个阅读分享者，而不仅\n仅是一个带货的网红主播。书香江苏形象大使苏先生在接受记者采访时表示，董主播把书推荐给那么多的读者，是\n好事。他认为，阅读推广人与董主播是不同的，“阅读推广”是“推广”，董主播只是“阅读推销”。\n  是推广还是推销？是高雅还是低俗？真不是一句话说得清楚的事。不可否认的是，越来越高的人气、越来越丰\n富的图书、丰富多彩的营销形式，对于我们这个社会来说似乎也不是坏事。",["4fbf1d8260d6665235b0.pdf",3]],"9c57cde35d866d4a":["材料7","材料7\n  最是书香能致远，从来善政不离书。各级领导干部带头读书、勤于读书，不仅是丰富自己、提升能力素质的有\n效途径，也必然会激发干部、党员和群众读书学习的积极性和主动性，对于书香社会建设有着巨大的推动作用。\n  2023年的夏天，国产动画电影《长安三万里》火爆出圈，大唐盛世中的李白、杜甫、高适等伟大诗人一一登上\n大银幕，不仅带我们感受群星闪耀的大唐风华，也让我们看到大唐诗人们追逐理想、实现人生抱负的恢宏故事。影\n片一上映便很快成为社会热门话题，影片中的48首诗歌也引发了全社会的古典诗歌热。8月中旬，J省文旅厅紫金图\n书馆党支部利用这一热点契机，组织全体党员干部开展“品诗词之美 扬文化自信”主题党日活动。\n  理论学习环节，全体党员集中学习了习近平总书记关于弘扬中华优秀传统文化的重要论述和在文化传承发展座\n谈会上的重要讲话，深刻领会了新时代新的文化使命重要论断的重大意义和内涵要义。诗词品评环节，青年党员代\n表以演讲、角色表演、PPT展示等方式分享自己钟爱的诗词篇章，并联系图书馆工作实际，诠释自己对诗词的解读\n与感悟。\n  文献部小戴：“大鹏一日同风起，扶摇直上九万里……宣父犹能畏后生，丈夫未可轻年少。”影片中李白的这首\n《上李邕》通过对大鹏形象的刻画与颂扬，表达了李白的凌云壮志和强烈的用世之心，全诗语气直率，充满了初生\n牛犊不怕虎的锐气。我觉得这首诗讲出了工作中我们年轻人常想说的心里话，我们生逢伟大年代啊，应当学习诗人\n这种不畏困难、勇于进取的勇气，实际工作中要敢于啃硬骨头，直面困难和挑战，展现青年人的责任和担当。\n  借阅部小吕：“莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。料峭春风吹酒\n醒，微冷，山头斜照却相迎。回首向来萧瑟处，归去，也无风雨也无晴。”宋代文学大家苏轼的《定风波·莫听穿林打\n叶声》一词，通过野外途中偶遇风雨这一生活中的小事，于简朴中见深意，于寻常处生奇景，表现出一种旷达超脱\n的胸襟，寄寓着超凡脱俗的人生理想。上片着眼于雨中，下片着眼于雨后，全词表现了一位正直文人在坎坷人生中\n的力求解脱之道，篇幅虽短，但意境深邃，内蕴丰富，诠释着作者的人生信念，展现着作者的精神追求。这首词我\n一直很喜欢，对于我们拓展人生境界、正确对待工作生活中的风风雨雨有着很大的启示。\n  “遥望历史风尘中的大唐气象，是无数中国人萦绕心头的文化乡愁。一部《长安三万里》，重现的不仅是昔日的\n时光，更是奔流在中华民族血脉中的诗情回望……”辅导部小万的激情演讲赢得了一片掌声。\n  “诵读唐诗宋词，是一代又一代中国人的个体经验与集体记忆，它是日常性的也是仪式性的。今天各位青年同志\n选取的诗词极富代表性，既有表现青年人伟大抱负的杰作，也有反映人生、仕途变迁感悟的名篇，各位同志不仅能\n对诗词本身丰富的文化蕴含深入阐发，而且能将古今对接，把个人对传统诗词文化的理解融入真切的现实生活\n中……”此次活动特邀嘉宾N大学胡教授对各位青年党员代表的表现进行了精彩点评。活动最后，党支部朱书记借\n\n《长安三万里》中的台词进行了总结：“‘诗在，长安就在’，我想他实际上说的是——文化在，人在，家国就在。中华\n民族历经五千年生生不息，盖源于此。当前广大文艺工作者在习近平总书记关于文艺工作的重要论述指引下，充分\n彰显文化自信，不断推出精品力作。这对于我们文化服务战线也是极大的鼓舞和鞭策，我们唯有不断学习、终生学\n习，人生道路才能更广，社会贡献才能更大。”朱书记还向大家推荐了《唐诗三百首》《习近平用典》两本书，并要\n求在下次活动中大家交流读书心得。\n  “这样的活动在我们文旅系统各部门、各单位比比皆是，我厅每年都会组织‘书香支部 品质阅读’活动，活动中会\n评比‘最美阅读案例’，发布‘最受党员干部欢迎的10本书’书单，目前已连续举办了8届。党员干部读书所产生的‘风成于\n上，俗化于下’的强烈示范效应，已成为引领全民阅读的重要力量。”J省文旅厅机关党委陈书记说。",["4fbf1d8260d6665235b0.pdf",3]],"89a8caff784c4b45":["材料8","材料8\n  时至今日，“全民阅读”已连续10年写入《政府工作报告》：“十四五”规划纲要明确提出“深入推进全民阅读，建\n设‘书香中国’”……全民阅读的制度保障更加完善。全国建成58.7万家农家书屋，3300多家公共图书馆全部免费向读\n者开放，14万多家职工书屋，覆盖职工8000多万人，城市书房、社区书屋等新型阅读空间如雨后春笋般快速增\n长……全民阅读基础设施更加充足。全国400多个城市常设读书节、读书月等，我国成年国民综合阅读率从2012年的\n76.3%上升至2022年的81.8%……全民阅读成效更加彰显。\n    新征程上，书香飘溢。在《致首届全民阅读大会举办的贺信》中，习近平总书记说：“中华民族自古提倡阅读，\n讲究格物致知、诚意正心，传承中华民族生生不息的精神，塑造中国人民自信自强的品格。希望广大党员、干部带\n头读书学习，修身养志，增长才干；希望孩子们养成阅读习惯，快乐阅读，健康成长；希望全社会都参与到阅读中\n来，形成爱读书、读好书、善读书的浓厚氛围。”在习近平总书记的大力倡导和亲自推动下，神州大地读书氛围愈发\n浓厚，文化自信更加坚定，奋进新征程的精神力量更加磅礴。",["4fbf1d8260d6665235b0.pdf",4]]}};
